// Comprova que el servidor respon amb status 200 OK
pm.test("Status code es 200", function () {
    pm.response.to.have.status(200);
});

// Comprova que el resultat siga un array [...]
pm.test("Devuelve un array", function () {
    pm.expect(pm.response.json()).to.be.an("array");
});

pm.collectionVariables.unset("tareaId");

if (pm.response.code === 201) {
    pm.collectionVariables.set(
        "tareaId",
        pm.response.json().id
    );
}

pm.test("Creación con 201", function () {
    pm.response.to.have.status(201);
});

pm.test("Id asignado y contenido esperado", function () {
    const cuerpo = pm.response.json();

    pm.expect(cuerpo.id).to.be.above(0);
    pm.expect(cuerpo.titulo).to.equal("Prueba A de la colección");
});

pm.test("Incluye Location", function () {
    pm.expect(
        pm.response.headers.get("Location")
    ).to.be.a("string").and.not.empty;
});

pm.collectionVariables.unset("tareaBId");

if (pm.response.code === 201) {
    pm.collectionVariables.set(
        "tareaBId",
        pm.response.json().id
    );
}

pm.test("Creación con 201", function () {
    pm.response.to.have.status(201);
});

pm.test("Id asignado y contenido esperado", function () {
    const cuerpo = pm.response.json();

    pm.expect(cuerpo.id).to.be.above(0);
    pm.expect(cuerpo.titulo).to.equal("Prueba B de la colección");
});

pm.test("Incluye Location", function () {
    pm.expect(
        pm.response.headers.get("Location")
    ).to.be.a("string").and.not.empty;
});

pm.test("Devuelve exactamente A", function () {
    const cuerpo = pm.response.json();

    pm.expect(cuerpo.id).to.equal(
        Number(pm.collectionVariables.get("tareaId"))
    );

    pm.expect(cuerpo.titulo).to.equal(
        "Prueba A de la colección"
    );
});

pm.test("Devuelve exactamente B", function () {
    const cuerpo = pm.response.json();

    pm.expect(cuerpo.id).to.equal(
        Number(pm.collectionVariables.get("tareaBId"))
    );

    pm.expect(cuerpo.titulo).to.equal(
        "Prueba B de la colección"
    );
});

pm.test("Borrado con 204 y sin cuerpo", function () {
    pm.response.to.have.status(204);
    pm.expect(pm.response.text()).to.equal("");
});

